CREATE TEMP TABLE commercial_report_checks(name text,passed boolean);
CREATE FUNCTION pg_temp.report_assert(v boolean,n text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF v IS DISTINCT FROM true THEN RAISE EXCEPTION 'REPORT FAIL: %',n;END IF;INSERT INTO commercial_report_checks VALUES(n,true);END$$;
CREATE FUNCTION pg_temp.report_query(c uuid,s text,customer text DEFAULT '',supplier text DEFAULT '',summary boolean DEFAULT false,f date DEFAULT current_date,t date DEFAULT current_date) RETURNS jsonb LANGUAGE plpgsql AS $$DECLARE cols jsonb;available jsonb;q jsonb;BEGIN
 SELECT columns INTO available FROM erp_reports_private.sources WHERE id=s;
 SELECT jsonb_agg(value) INTO cols FROM jsonb_array_elements_text(available) WHERE value=ANY(CASE WHEN summary THEN ARRAY['amount','net','tax','paid','refunded','outstanding','remaining','received','issued','debit','credit','balance','count'] ELSE ARRAY['number','customer','supplier','status','electronicStatus','kind','amount','net','tax','paid','refunded','outstanding','remaining','received','issued','debit','credit','balance','count'] END);
 q:=jsonb_build_object('source',s,'from',f,'to',t,'columns',cols,'groupBy','[]'::jsonb,'summary',summary,'filters',CASE WHEN customer<>'' THEN jsonb_build_object('customer',customer) WHEN supplier<>'' THEN jsonb_build_object('supplier',supplier) ELSE '{}'::jsonb END,'conditions','[]'::jsonb,'conditionMode','all','sortBy',CASE WHEN available?'amount' THEN 'amount' ELSE 'count' END,'descending',false,'offset',0,'limit',500);
 RETURN public.erp_branch_execute(c,'erp_report_run',jsonb_build_object('p_cafe_id',c,'p_query',q),public.erp_branch_context(c)->'scope');
END$$;
CREATE FUNCTION pg_temp.report_advance(c uuid,advance uuid,customer uuid,available numeric,ordinary numeric,label text) RETURNS void LANGUAGE plpgsql AS $$DECLARE name text;r jsonb;summary jsonb;today date:=current_date;before_ledger text;after_ledger text;kind text;metric text;original jsonb;current_rows jsonb;canonical_total numeric;advance_total numeric;BEGIN
 SELECT p.name INTO name FROM public.bf_parties p WHERE cafe_id=c AND id=customer;SELECT md5(jsonb_agg(to_jsonb(j) ORDER BY j.id)::text) INTO before_ledger FROM public.bf_journal j WHERE cafe_id=c;
 r:=pg_temp.report_query(c,'sales',name);PERFORM pg_temp.report_assert(EXISTS(SELECT 1 FROM jsonb_array_elements(r->'rows')x WHERE x->>'id'=advance::text AND(x->>'amount')::numeric=46 AND(x->>'tax')::numeric=6),label||': canonical sales includes actual advance and tax');
 canonical_total:=coalesce((r#>>'{totals,amount}')::numeric,0);SELECT coalesce(sum(d.total),0) INTO advance_total FROM public.erp_contracting_advance_invoices a JOIN public.bf_documents d ON d.cafe_id=a.cafe_id AND d.id=a.invoice_id WHERE d.cafe_id=c AND d.party_id=customer;
 r:=pg_temp.report_query(c,'business-sales',name);PERFORM pg_temp.report_assert(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'rows')x WHERE x->>'id'=advance::text),label||': business revenue excludes advance');
 summary:=pg_temp.report_query(c,'business-sales',name,'',true);PERFORM pg_temp.report_assert(coalesce((r#>>'{totals,amount}')::numeric,0)=coalesce((summary#>>'{totals,amount}')::numeric,0),label||': business detail and summary agree');
 PERFORM pg_temp.report_assert(canonical_total-coalesce((r#>>'{totals,amount}')::numeric,0)=advance_total,label||': business excludes exactly advances and keeps genuine commercial invoices');
 PERFORM pg_temp.report_assert(coalesce((summary#>>'{rows,0,amount}')::numeric,0)=coalesce((r#>>'{totals,amount}')::numeric,0),label||': summary row matches actual business total');
 r:=pg_temp.report_query(c,'sales-lines',name);PERFORM pg_temp.report_assert(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'rows')x JOIN public.bf_document_lines l ON l.id::text=x->>'id' JOIN public.bf_documents d ON d.cafe_id=l.cafe_id AND d.id=l.document_id WHERE d.id=advance OR d.reference_id=advance),label||': sales lines exclude advance and its credits');
 PERFORM pg_temp.report_assert(EXISTS(SELECT 1 FROM erp_reports_private.financial_facts_before_commercial_adjustments(c,'sales-lines',today,today)x JOIN public.bf_document_lines l ON l.id::text=x->>'id' WHERE l.cafe_id=c AND l.document_id=advance),label||': positive baseline original sales line exists before exclusion');
 r:=pg_temp.report_query(c,'customer-credits',name);PERFORM pg_temp.report_assert(coalesce((r#>>'{totals,remaining}')::numeric,0)=available+ordinary,label||': current credit total has no double count');
 PERFORM pg_temp.report_assert((available=0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'rows')x WHERE x->>'id'='advance-invoice:'||advance::text)) OR EXISTS(SELECT 1 FROM jsonb_array_elements(r->'rows')x WHERE x->>'id'='advance-invoice:'||advance::text AND(x->>'remaining')::numeric=available AND x->>'number'='ADV-0001'),label||': advance row current remaining and actual display number');
 summary:=pg_temp.report_query(c,'customer-credits',name,'',true,today-1000,today-999);PERFORM pg_temp.report_assert(coalesce((summary#>>'{totals,remaining}')::numeric,0)=available+ordinary,label||': old date range explicitly returns current available balance');
 FOREACH kind IN ARRAY ARRAY['cash-flow','journal','sales-payments'] LOOP
  SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') INTO original FROM erp_reports_private.financial_facts_before_commercial_adjustments(c,kind,today,today)x;
  SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') INTO current_rows FROM erp_reports_private.financial_facts(c,kind,today,today)x;
  PERFORM pg_temp.report_assert(original=current_rows,label||': unchanged source '||kind);
  metric:=CASE kind WHEN 'cash-flow' THEN 'received' WHEN 'journal' THEN 'debit' ELSE 'amount' END;r:=pg_temp.report_query(c,kind,name);
  PERFORM pg_temp.report_assert(coalesce((r->'totals'->>metric)::numeric,0)=(SELECT coalesce(sum((x->>metric)::numeric),0) FROM jsonb_array_elements(original)x WHERE x->>'customer'=name AND(x->>'date')::date BETWEEN today AND today),label||': public report retains source total '||kind);
 END LOOP;
 SELECT md5(jsonb_agg(to_jsonb(j) ORDER BY j.id)::text) INTO after_ledger FROM public.bf_journal j WHERE cafe_id=c;PERFORM pg_temp.report_assert(before_ledger=after_ledger,label||': report never mutates actual ledger');
END$$;
CREATE FUNCTION pg_temp.report_purchase(c uuid,p_note uuid,posting uuid,expected_status text,expected_paid numeric,expected_outstanding numeric,label text) RETURNS void LANGUAGE plpgsql AS $$DECLARE supplier_name text;code text;r jsonb;row jsonb;summary jsonb;BEGIN
 SELECT p.name,n.code INTO supplier_name,code FROM public.erp_purchase_credit_notes n JOIN public.bf_documents d ON d.cafe_id=n.cafe_id AND d.id=n.source_document_id JOIN public.bf_parties p ON p.cafe_id=d.cafe_id AND p.id=d.party_id WHERE n.cafe_id=c AND n.id=p_note;
 r:=pg_temp.report_query(c,'purchase-documents','',supplier_name);SELECT x INTO row FROM jsonb_array_elements(r->'rows')x WHERE x->>'id'=posting::text;
 PERFORM pg_temp.report_assert(row IS NOT NULL AND row->>'number'=code AND row->>'href'='/dashboard/system/purchases/credit-notes/'||p_note::text,label||': actual credit code and canonical link');
 PERFORM pg_temp.report_assert(row->>'status'=expected_status AND(row->>'paid')::numeric=expected_paid AND(row->>'outstanding')::numeric=expected_outstanding,label||': actual payment and reversal state');
 summary:=pg_temp.report_query(c,'purchase-documents','',supplier_name,true);PERFORM pg_temp.report_assert(r->'totals'=summary->'totals',label||': purchase detail and summary totals agree');
 PERFORM pg_temp.report_assert(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'rows')x JOIN public.erp_purchase_credit_postings h ON h.cafe_id=c AND h.reversal_document_id::text=x->>'id'),label||': no synthetic duplicate reversal invoice fact');
END$$;
